    bool SetVisibleToAll(CEntityInstance* entity, bool visible, int channel) override { return transmit::transmitManager.SetVisibleToAll(static_cast<decltype(entity)&&>(entity), static_cast<decltype(visible)&&>(visible), static_cast<decltype(channel)&&>(channel)); }
    bool IsVisible(CEntityInstance* entity, CPlayerSlot viewer) override { return transmit::transmitManager.IsVisible(static_cast<decltype(entity)&&>(entity), static_cast<decltype(viewer)&&>(viewer)); }
    bool IsHiddenOnChannel(CEntityInstance* entity, CPlayerSlot viewer, int channel) override { return transmit::transmitManager.IsHiddenOnChannel(static_cast<decltype(entity)&&>(entity), static_cast<decltype(viewer)&&>(viewer), static_cast<decltype(channel)&&>(channel)); }
    bool SetBlockAll(CEntityInstance* entity, bool block) override { return transmit::transmitManager.SetBlockAll(static_cast<decltype(entity)&&>(entity), static_cast<decltype(block)&&>(block)); }
    bool GetBlockAll(CEntityInstance* entity) override { return transmit::transmitManager.GetBlockAll(static_cast<decltype(entity)&&>(entity)); }
    bool SetOwner(CEntityInstance* entity, CEntityInstance* owner) override { return transmit::transmitManager.SetOwner(static_cast<decltype(entity)&&>(entity), static_cast<decltype(owner)&&>(owner)); }
    CEntityInstance* GetOwner(CEntityInstance* entity) override { return transmit::transmitManager.GetOwner(static_cast<decltype(entity)&&>(entity)); }
    void ResetViewer(CPlayerSlot viewer) override { return transmit::transmitManager.ResetViewer(static_cast<decltype(viewer)&&>(viewer)); }
    Source2ModTransmitHookId HookCheckTransmit(CheckTransmitHook handler) override { return transmit::transmitManager.HookCheckTransmit(m_owner, static_cast<decltype(handler)&&>(handler)); }
    bool UnhookCheckTransmit(const CheckTransmitHook& handler) override { return transmit::transmitManager.UnhookCheckTransmit(m_owner, static_cast<decltype(handler)&&>(handler)); }
    bool UnhookCheckTransmit(Source2ModTransmitHookId id) override { return transmit::transmitManager.UnhookCheckTransmit(static_cast<decltype(id)&&>(id)); }

